"""Functional tests for the public storefront (local preview mode). Run: python3 build/test_public.py"""
import time, subprocess, os, json, sys
from playwright.sync_api import sync_playwright
EXE = os.environ.get("CHROME", "/opt/pw-browsers/chromium_headless_shell-1194/chrome-linux/headless_shell")
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); OUT = "/tmp/shots"; os.makedirs(OUT, exist_ok=True)
srv = subprocess.Popen(["python3", "-m", "http.server", "8077"], cwd=ROOT, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL); time.sleep(1)
B = "http://localhost:8077/"; res = []; errs = []
def check(name, ok, info=""): res.append((name, bool(ok), info)); print(("PASS " if ok else "FAIL ") + name + (f"  [{info}]" if info and not ok else ""))
try:
    with sync_playwright() as p:
        b = p.chromium.launch(executable_path=EXE, args=["--no-sandbox"])
        ctx = b.new_context(viewport=dict(width=1440, height=900)); pg = ctx.new_page()
        pg.on("pageerror", lambda e: errs.append(str(e)[:200])); pg.on("console", lambda m: errs.append(m.text[:160]) if m.type == "error" else None)
        # ---- home / slideshow
        pg.goto(B + "index.html"); pg.wait_for_timeout(1500)
        slides = pg.locator(".slide"); check("home has 3 slides", slides.count() == 3, slides.count())
        first = pg.locator(".slide.on .s-photo").get_attribute("src"); check("first slide uses image 5 (slide-first.jpg)", "slide-first.jpg" in first, first)
        pg.click("#hn"); pg.wait_for_timeout(1300); check("next arrow shows LFG layered slide", "lfg-hero-cap.jpg" in pg.locator(".slide.on .s-photo").get_attribute("src") and pg.locator(".slide.on .s-logo").count() == 1)
        pg.screenshot(path=f"{OUT}/t_slide2.png"); pg.click("#hn"); pg.wait_for_timeout(1300); check("third slide is Her District with its logo behind", "hd-hero-tank.jpg" in pg.locator(".slide.on .s-photo").get_attribute("src") and "her-district-logo" in pg.locator(".slide.on .s-logo").get_attribute("src"))
        pg.screenshot(path=f"{OUT}/t_slide3.png")
        pg.wait_for_timeout(7200); check("slideshow auto-advances", pg.locator(".slide.on").evaluate("e=>[...e.parentNode.children].indexOf(e)") == 0)
        cards = pg.locator(".bcard"); check("two brand cards", cards.count() == 2)
        check("LFG card has DROPPING SOON label", "dropping soon" in pg.locator('.bcard[data-brand="lfg"] .soon-tag').inner_text().lower())
        check("LFG card uses images 3 and 4", pg.locator('.bcard[data-brand="lfg"] img').evaluate_all("els=>els.map(e=>e.src)").__len__() >= 2)
        pg.screenshot(path=f"{OUT}/t_collections.png", full_page=False)
        pg.locator('.bcard[data-brand="lfg"] .bcard-imgs').click(); pg.wait_for_url("**/lads-from-ghana.html"); pg.wait_for_timeout(900)
        check("clicking LFG image opens coming-soon page", pg.locator(".soon-hero").count() == 1 and pg.locator(".pcard").count() == 0)
        check("no add-to-cart/prices on LFG page", pg.locator("text=GH₵").count() == 0)
        pg.goto(B + "index.html"); pg.wait_for_timeout(800); pg.locator('.bcard[data-brand="her-district"] .go').click(); pg.wait_for_url("**/her-district.html"); pg.wait_for_timeout(800)
        check("Her District page lists 2 products", pg.locator(".pcard").count() == 2)
        check("both products GH₵150.00", pg.locator(".pcard .price").all_inner_texts() == ["GH₵150.00", "GH₵150.00"], pg.locator(".pcard .price").all_inner_texts())
        ig = pg.locator('a[href*="instagram.com/her.dst"]'); check("Instagram link points to @her.dst profile", ig.count() >= 2 and all(h == "https://www.instagram.com/her.dst/?__pwa=1#" for h in ig.evaluate_all("e=>e.map(x=>x.href)")), ig.evaluate_all("e=>e.map(x=>x.href)"))
        # ---- product: sleeveless
        pg.locator(".pcard").nth(0).click(); pg.wait_for_url("**/product.html?p=her-district-sleeveless-top"); pg.wait_for_timeout(900)
        imgs = pg.locator(".gal-track img").evaluate_all("e=>e.map(x=>x.getAttribute('src').split('/').pop())")
        check("sleeveless: image 7, 8, 9 in order", imgs == ["hd-sleeveless-1.jpg", "hd-sleeveless-2.jpg", "hd-sleeveless-3.jpg"], imgs)
        check("sleeveless: opens on first image", pg.locator(".gal-count").inner_text() == "1 / 3")
        pg.click(".gal-arrow.next"); pg.wait_for_timeout(700); check("arrow goes to 2/3", pg.locator(".gal-count").inner_text() == "2 / 3")
        pg.locator(".gal-thumbs button").nth(2).click(); pg.wait_for_timeout(700); check("thumbnail goes to 3/3", pg.locator(".gal-count").inner_text() == "3 / 3")
        # swipe (drag) back one image
        box = pg.locator(".gal-main").bounding_box(); pg.mouse.move(box["x"] + box["width"] * .7, box["y"] + 200); pg.mouse.down(); pg.mouse.move(box["x"] + box["width"] * .2, box["y"] + 200, steps=8); pg.mouse.up(); pg.wait_for_timeout(700)
        check("drag/swipe left from 3/3 wraps to 1/3", pg.locator(".gal-count").inner_text() == "1 / 3", pg.locator(".gal-count").inner_text())
        pg.locator("#qp").click(); pg.locator("#add").click(); pg.wait_for_timeout(400)
        check("cart badge shows 2 after adding qty 2", pg.locator("#cartCount").inner_text() == "2")
        # ---- crop top
        pg.goto(B + "product.html?p=her-district-crop-top"); pg.wait_for_timeout(900)
        imgs = pg.locator(".gal-track img").evaluate_all("e=>e.map(x=>x.getAttribute('src').split('/').pop())"); check("crop: image 10, 11, 12 in order", imgs == ["hd-crop-1.jpg", "hd-crop-2.jpg", "hd-crop-3.jpg"], imgs)
        pg.locator("#add").click(); pg.wait_for_timeout(400); check("cart badge shows 3", pg.locator("#cartCount").inner_text() == "3")
        # ---- cart
        pg.goto(B + "cart.html"); pg.wait_for_timeout(900)
        check("cart has 2 lines", pg.locator(".line").count() == 2)
        check("subtotal = GH₵450.00 (3 x 150)", "GH₵450.00" in pg.locator("#st").inner_text(), pg.locator("#st").inner_text())
        pg.locator('button[data-a="p"]').first.click(); pg.wait_for_timeout(300); check("increase qty -> GH₵600.00", "GH₵600.00" in pg.locator("#st").inner_text(), pg.locator("#st").inner_text())
        pg.locator('button[data-a="m"]').first.click(); pg.wait_for_timeout(200); check("decrease -> GH₵450.00", "GH₵450.00" in pg.locator("#st").inner_text(), pg.locator("#st").inner_text())
        for _ in range(2): pg.locator('button[data-a="m"]').first.click(); pg.wait_for_timeout(200)
        check("decreasing to 0 removes the line", pg.locator(".line").count() == 1 and "GH₵150.00" in pg.locator("#st").inner_text(), pg.locator("#st").inner_text())
        pg.reload(); pg.wait_for_timeout(900); check("cart persists after refresh", pg.locator(".line").count() == 1)
        pg.locator('button[data-a="r"]').first.click(); pg.wait_for_timeout(300); check("remove empties bag", "empty" in pg.locator("#app").inner_text().lower())
        pg.goto(B + "product.html?p=her-district-crop-top"); pg.wait_for_timeout(800); pg.locator("#add").click(); pg.goto(B + "cart.html"); pg.wait_for_timeout(800)
        pg.locator("#place").click(); pg.wait_for_timeout(300); check("checkout validates empty form", pg.locator("#cerr").is_visible())
        pg.fill('input[name=name]', "Ama Test"); pg.fill('input[name=phone]', "024 123 4567"); pg.fill('input[name=address]', "East Legon, Accra"); pg.locator("#place").click(); pg.wait_for_timeout(900)
        txt = pg.locator("#app").inner_text(); check("order placed, number + total shown, payment NOT claimed", "ORD-1001" in txt and "GH₵150.00" in txt and "Payment has not been taken" in txt, txt[:160])
        check("cart cleared after order", pg.evaluate("localStorage.getItem('hd_cart_v1')") == "[]")
        orders = pg.evaluate("JSON.parse(localStorage.getItem('hd_local_db_v1')).orders"); check("order stored unpaid/pending with price snapshot", len(orders) == 1 and orders[0]["payment_status"] == "unpaid" and orders[0]["status"] == "pending" and orders[0]["order_items"][0]["unit_price"] == 150, orders)
        # tamper test: a forged price must be ignored
        r = pg.evaluate("""async()=>{const m=await import('/js/store.js');const d=await m.Store.loadAll();const p=d.products[0];try{const o=await m.Store.placeOrder({name:'X Y',phone:'0241234567',address:'Accra road'},[{product_id:p.id,quantity:1,price:1}]);return o}catch(e){return {err:e.message}}}""")
        check("server-side pricing ignores client price", r.get("total") == 150, r)
        r2 = pg.evaluate("""async()=>{const m=await import('/js/store.js');try{await m.Store.placeOrder({name:'X Y',phone:'0241234567',address:'Accra road'},[{product_id:'nope',quantity:1}]);return 'accepted'}catch(e){return e.message}}""")
        check("unknown product rejected", "no longer available" in r2, r2)
        # ---- lookbook
        pg.goto(B + "lookbook.html"); pg.wait_for_timeout(1200)
        srcs = pg.locator(".mi img").evaluate_all("e=>e.map(x=>x.getAttribute('src').split('/').pop())")
        check("lookbook has 13 images incl. new 13-17", len(srcs) == 13 and all(f"look-{n}.jpg" in srcs for n in (13, 14, 15, 16, 17)), srcs)
        pg.locator('.chip[data-f="her-district"]').click(); pg.wait_for_timeout(300); check("filter Her District shows 2", pg.locator(".mi").count() == 2)
        pg.locator(".mi").first.click(); pg.wait_for_timeout(300); check("lightbox opens", pg.locator(".lb.on").count() == 1); pg.keyboard.press("Escape")
        pg.locator('.chip[data-f="all"]').click(); pg.wait_for_timeout(300); check("single shared lookbook (no second page)", not os.path.exists(os.path.join(ROOT, "lookbook-lfg.html")) and pg.locator(".mi").count() == 13)
        pg.screenshot(path=f"{OUT}/t_lookbook.png", full_page=True)
        ctx.close()
        # ---- mobile
        m = b.new_context(viewport=dict(width=390, height=844), has_touch=True, is_mobile=True); mp = m.new_page(); mp.on("pageerror", lambda e: errs.append("M:" + str(e)[:200]))
        mp.goto(B + "index.html"); mp.wait_for_timeout(1400); mp.screenshot(path=f"{OUT}/t_m_home.png")
        mp.locator("#burger").tap(); mp.wait_for_timeout(700); check("mobile menu opens", mp.locator("#hdr.open").count() == 1); mp.screenshot(path=f"{OUT}/t_m_menu.png")
        sw = mp.evaluate("document.documentElement.scrollWidth"); check("no horizontal overflow on mobile home", sw <= 392, sw)
        for u in ("her-district.html", "product.html?p=her-district-crop-top", "lookbook.html", "cart.html", "lads-from-ghana.html"):
            mp.goto(B + u); mp.wait_for_timeout(900); w = mp.evaluate("document.documentElement.scrollWidth"); check(f"no horizontal overflow: {u}", w <= 392, w)
        m.close(); b.close()
finally:
    srv.terminate()
bad = [r for r in res if not r[1]]; print(f"\n{len(res)-len(bad)}/{len(res)} passed"); print("console/page errors:", errs[:8]); sys.exit(1 if bad else 0)
